// PiccoloComp.dll MfPcParser.cpp (0x100119c0-0x100157c0): the parser of the
// Piccolo language, generated by Berkeley yacc 1.9 (prefix "pc") from the
// grammar below. The actions build the expression trees and the code of the
// statements (MfPcChunkList) and hand every finished function to the compiler.
//
// The grammar (rule numbers as in the tables):
//   1 program: declarations main_code              2 | declarations functions
//   3 declarations: top_decls_opt
//   4 top_decl: declaration_statement               5 | use_statement
//   6 top_decls: top_decl                           7 | top_decls top_decl
//   8 top_decls_opt: /* empty */                   9 | top_decls
//  10 functions: function_list_opt
//  11 function_list: function                      12 | function_list function
//  13 function_list_opt: /* empty */               14 | function_list
//  15 main_code: compound_statement
//  16 $$1: /* empty */
//  17 function: FUNCTION function_head $$1 parameters function_body
//  18 function_head: identifier '('                19 | error '('
//  20 parameters: identifier_list_opt ')'          21 | error ')'
//  22 function_body: compound_statement            23 | error '}'
//  24 identifier_list: identifier                  25 | identifier_list ',' identifier
//  26 identifier_list_opt: /* empty */             27 | identifier_list
//  28 use_statement: USE identifier STRING ';'
//  29 statement_list: statement                    30 | statement_list statement
//  31 statement_list_opt: /* empty */              32 | statement_list
//  33 statement: compound_statement   34 | declaration_statement   35 | expression_statement
//  36 | selection_statement   37 | iteration_statement   38 | labeled_statement
//  39 | jump_statement   40 | error ';'
//  41 $$2: /* empty */
//  42 compound_statement: '{' $$2 statement_list_opt '}'
//  43 declaration_statement: declaration
//  44 expression_statement: expression_opt ';'
//  45 selection_statement: IF '(' expression ')' statement
//  46 | IF '(' expression ')' statement ELSE statement
//  47 $$3: /* empty */
//  48 | SWITCH $$3 '(' expression ')' compound_statement
//  49 $$4: /* empty */
//  50 iteration_statement: WHILE $$4 '(' expression ')' statement
//  51 $$5: /* empty */
//  52 | DO $$5 statement WHILE '(' expression ')'
//  53 $$6: /* empty */
//  54 | FOR $$6 '(' for_init expression_opt ';' expression_opt ')' statement
//  55 for_init: expression_statement               56 | declaration_statement
//  57 $$7: /* empty */
//  58 labeled_statement: identifier ':' $$7 statement
//  59 | CASE constant_expression ':' statement    60 | DEFAULT ':' statement
//  61 jump_statement: BREAK ';'   62 | CONTINUE ';'   63 | RETURN expression_opt ';'
//  64 | GOTO identifier ';'
//  65 declaration: declaration_kind declarator_list ';'
//  66 declaration_kind: VAR   67 | CONST   68 | GLOBAL   69 | GLOBAL VAR
//  70 declarator_list: declarator                  71 | declarator_list ',' declarator
//  72 declarator: declarator_name initializer_opt
//  73 declarator_name: identifier                  74 | array_head array_size
//  75 array_head: identifier '['                   76 | error '['
//  77 array_size: constant_expression_opt ']'      78 | error ']'
//  79 initializer: '=' expression                  80 | '=' '{' expression_list_opt '}'
//  81 initializer_opt: /* empty */                 82 | initializer
//  83 expression_list: expression                  84 | expression_list ',' expression
//  85 expression_list_opt: /* empty */             86 | expression_list
//  87 expression: assignment                       88 | expression ',' assignment
//  89 expression_opt: /* empty */                  90 | expression
//  91 primary: literal   92 | THIS   93 | NIL   94 | '(' expression ')'   95 | identifier
//  96 postfix: primary   97 | postfix '[' expression ']'   98 | postfix '(' argument_list_opt ')'
//  99 | postfix '.' identifier   100 | postfix '.' '#' identifier
// 101 | postfix INCR   102 | postfix DECR
// 103 argument_list: assignment                   104 | argument_list ',' assignment
// 105 argument_list_opt: /* empty */              106 | argument_list
// 107 unary: postfix   108 | INCR unary   109 | DECR unary   110 | '+' unary
// 111 | '-' unary   112 | '!' unary   113 | '~' unary   114 | '$' unary   115 | new_expression
// 116 new_expression: NEW identifier
// 117 | NEW identifier SCOPE identifier '(' argument_list_opt ')'
// 118 | NEW identifier '(' argument_list_opt ')'
// 119-149 the binary operators by precedence (* / %, + -, << >>, < > <= >=,
//         == !=, &, ^, |, &&, ||, ?:) down to
// 149 assignment: conditional    150 | lvalue assignment_operator assignment
// 151 lvalue: unary
// 152-162 assignment_operator: = *= /= %= += -= <<= >>= &= ^= |=
// 163 constant_expression: conditional
// 164 constant_expression_opt: /* empty */         165 | constant_expression
// 166 literal: INTEGER   167 | FLOAT   168 | STRING   169 | CHARACTER
// 170 identifier: IDENTIFIER
